"""Media probe tests against real files generated by FFmpeg's lavfi sources.

Synthetic media keeps the suite hermetic: no sample files, no network, a couple
of kilobytes each and a few milliseconds of encoding per case.
"""

from __future__ import annotations

import subprocess
from pathlib import Path

import pytest

from dosubs.media import probe
from dosubs.media.probe import (
    SUPPORTED_EXT,
    MediaError,
    expand_inputs,
    ffmpeg_path,
    have_ffmpeg,
    is_supported,
    media_kind,
)

requires_ffmpeg = pytest.mark.skipif(
    not have_ffmpeg(), reason="ffmpeg/ffprobe not available on PATH"
)


def _ffmpeg(*args: str) -> None:
    """Run ffmpeg, failing loudly so a broken encoder never looks like a bug."""
    completed = subprocess.run(
        [ffmpeg_path(), "-hide_banner", "-loglevel", "error", "-y", *args],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
        creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        check=False,
    )
    assert completed.returncode == 0, completed.stderr


@pytest.fixture(scope="session")
def media(tmp_path_factory: pytest.TempPathFactory) -> dict[str, Path]:
    """One video+audio, one audio-only and one video-only file."""
    if not have_ffmpeg():
        pytest.skip("ffmpeg/ffprobe not available")

    directory = tmp_path_factory.mktemp("media")
    video_with_audio = directory / "av.mp4"
    audio_only = directory / "tone.mp3"
    video_only = directory / "silent.mkv"

    _ffmpeg(
        "-f", "lavfi", "-i", "testsrc=size=160x120:rate=10",
        "-f", "lavfi", "-i", "sine=frequency=440",
        "-t", "2", "-shortest",
        "-c:v", "libx264", "-pix_fmt", "yuv420p", "-c:a", "aac",
        str(video_with_audio),
    )
    _ffmpeg(
        "-f", "lavfi", "-i", "sine=frequency=440",
        "-t", "1", "-c:a", "libmp3lame",
        str(audio_only),
    )
    _ffmpeg(
        "-f", "lavfi", "-i", "testsrc=size=160x120:rate=10",
        "-t", "1", "-c:v", "libx264", "-pix_fmt", "yuv420p", "-an",
        str(video_only),
    )
    return {"av": video_with_audio, "audio": audio_only, "video_only": video_only}


# --------------------------------------------------------------------------- #
# Extension classification
# --------------------------------------------------------------------------- #


def test_supported_extension_sets() -> None:
    assert ".mp4" in SUPPORTED_EXT and ".mkv" in SUPPORTED_EXT and ".mp3" in probe.SUPPORTED_AUDIO_EXT
    assert SUPPORTED_EXT == probe.SUPPORTED_VIDEO_EXT | probe.SUPPORTED_AUDIO_EXT
    assert is_supported("Clip.MP4") is True
    assert is_supported(".gitignore") is False
    assert is_supported("notes.txt") is False


def test_media_kind_only_audio_extensions_are_audio() -> None:
    assert media_kind("song.mp3") == "audio"
    assert media_kind("book.m4b") == "audio"
    assert media_kind("clip.mkv") == "video"
    assert media_kind("clip.mp4") == "video"


def test_have_ffmpeg_never_raises() -> None:
    assert isinstance(have_ffmpeg(), bool)


# --------------------------------------------------------------------------- #
# probe_media
# --------------------------------------------------------------------------- #


@requires_ffmpeg
def test_probe_video_with_audio(media: dict[str, Path]) -> None:
    path = media["av"]
    info = probe.probe_media(path)

    assert info.path == path
    assert abs(info.duration_s - 2.0) < 0.5
    assert info.size_bytes > 0
    assert info.has_audio is True
    assert info.audio_codec == "aac"
    assert info.video_codec is not None
    assert info.has_video is True
    assert info.container


@requires_ffmpeg
def test_probe_audio_only_file(media: dict[str, Path]) -> None:
    info = probe.probe_media(media["audio"])

    assert info.has_audio is True
    assert info.audio_codec == "mp3"
    assert info.video_codec is None
    assert info.has_video is False
    assert abs(info.duration_s - 1.0) < 0.5


@requires_ffmpeg
def test_probe_video_without_audio_stream_does_not_raise(media: dict[str, Path]) -> None:
    info = probe.probe_media(media["video_only"])

    assert info.has_audio is False
    assert info.audio_codec is None
    assert info.video_codec is not None
    assert info.duration_s > 0


def test_probe_missing_file_raises_with_path(tmp_path: Path) -> None:
    missing = tmp_path / "nope.mp4"
    with pytest.raises(MediaError) as excinfo:
        probe.probe_media(missing)
    assert str(missing) in str(excinfo.value)


def test_probe_unsupported_container_raises_with_path(tmp_path: Path) -> None:
    text = tmp_path / "notes.txt"
    text.write_text("not media", encoding="utf-8")
    with pytest.raises(MediaError) as excinfo:
        probe.probe_media(text)
    assert str(text) in str(excinfo.value)


@requires_ffmpeg
def test_probe_garbage_media_raises_with_path(tmp_path: Path) -> None:
    garbage = tmp_path / "broken.mp4"
    garbage.write_bytes(b"\x00\x01\x02 definitely not an mp4")
    with pytest.raises(MediaError) as excinfo:
        probe.probe_media(garbage)
    assert str(garbage) in str(excinfo.value)


# --------------------------------------------------------------------------- #
# expand_inputs
# --------------------------------------------------------------------------- #


def test_expand_inputs_scans_one_level_and_filters(tmp_path: Path) -> None:
    directory = tmp_path / "inbox"
    directory.mkdir()
    supported = directory / "clip.mp4"
    supported.write_bytes(b"")
    (directory / "list.txt").write_text("ignored", encoding="utf-8")
    subdirectory = directory / "nested"
    subdirectory.mkdir()
    (subdirectory / "deep.mp4").write_bytes(b"")

    assert expand_inputs([directory]) == [supported]


def test_expand_inputs_deduplicates_case_insensitively(tmp_path: Path) -> None:
    directory = tmp_path / "dup"
    directory.mkdir()
    supported = directory / "clip.mp4"
    supported.write_bytes(b"")

    differently_cased = directory / "CLIP.MP4"  # same file on Windows

    result = expand_inputs([directory, directory, supported, differently_cased])
    assert result == [supported]


def test_expand_inputs_accepts_supported_files_and_skips_others(tmp_path: Path) -> None:
    good = tmp_path / "a.mp3"
    good.write_bytes(b"")
    bad = tmp_path / "b.txt"
    bad.write_text("x", encoding="utf-8")

    assert expand_inputs([good, bad]) == [good]


def test_expand_inputs_sorted(tmp_path: Path) -> None:
    for name in ("b.mp4", "a.mp3", "c.mkv"):
        (tmp_path / name).write_bytes(b"")

    names = [path.name for path in expand_inputs([tmp_path])]
    assert names == ["a.mp3", "b.mp4", "c.mkv"]


def test_expand_inputs_missing_path_raises(tmp_path: Path) -> None:
    missing = tmp_path / "ghost.mp4"
    with pytest.raises(MediaError) as excinfo:
        expand_inputs([missing])
    assert str(missing) in str(excinfo.value)
